"""Daily signups load: vendor feed -> DuckDB warehouse, on Airflow."""

import json
from datetime import date, datetime
from pathlib import Path

import duckdb
from airflow.sdk import Variable, dag, get_current_context, task

FEED = Path(__file__).parent.parent / "data" / "signups.json"


def parse_date(raw: str) -> date:
    """Accept ISO (YYYY-MM-DD) and the vendor's DD/MM/YYYY; fail loudly on anything else."""
    raw = raw.strip()
    if "/" in raw:
        return datetime.strptime(raw, "%d/%m/%Y").date()
    return date.fromisoformat(raw)


def parse_row(row: dict) -> tuple:
    return (int(row["id"]), row["email"].strip().lower(), parse_date(row["signup_date"]),
            row["plan"])


@dag(dag_id="signups_daily", schedule=None, catchup=False, tags=["demo"],
     params={"target_schema": "analytics"})
def signups_daily():
    @task
    def load_signups() -> int:
        schema = get_current_context()["params"]["target_schema"]
        rows = [parse_row(r) for r in json.loads(FEED.read_text())]
        con = duckdb.connect(Variable.get("warehouse_path"))
        con.execute(f"CREATE SCHEMA IF NOT EXISTS {schema}")
        con.execute(f"CREATE OR REPLACE TABLE {schema}.signups "
                    "(signup_id INTEGER, email VARCHAR, signup_date DATE, plan VARCHAR)")
        con.executemany(f"INSERT INTO {schema}.signups VALUES (?, ?, ?, ?)", rows)
        count = con.execute(f"SELECT count(*) FROM {schema}.signups").fetchone()[0]
        con.close()
        return count

    load_signups()


signups_daily()

